/**
 * This component wraps ContentfulHero with Ninetailed Experience functionality.
 * It's lazy-loaded to prevent Ninetailed from being bundled in the SSR bundle.
 *
 * IMPORTANT: This component MUST be rendered inside a NinetailedProvider.
 * ContentfulHero.tsx handles this by only rendering this component when
 * there are experiences AND isDomReady (ensuring NinetailedWrapper is mounted).
 */
import {Experience} from '@ninetailed/experience.js-react'
import type {Baseline} from '@ninetailed/experience.js'
import {ExperienceMapper} from '@ninetailed/experience.js-utils-contentful'

import type {NinetailedExperienceEntry} from '../../../lib/utils/contentful-ninetailed'
import {ContentfulHeroLayout} from './ContentfulHeroLayout'
import type {ContentfulHeroProps} from './contentful-hero.types'
import type {PrimerComponentHero} from '../../../schemas/contentful/contentTypes/primerComponentHero'

interface ContentfulHeroExperiencesProps extends ContentfulHeroProps {
  rawExperiences: NinetailedExperienceEntry[]
}

export default function ContentfulHeroExperiences({
  component,
  paddingBlockEnd,
  analyticsContext,
  rawExperiences,
  ...props
}: ContentfulHeroExperiencesProps) {
  // Map experiences to extract heading and description for A/B testing
  // Variants are Contentful Hero entries with the same field structure
  const experiences = rawExperiences.filter(ExperienceMapper.isExperienceEntry).map(experience =>
    ExperienceMapper.mapCustomExperience(experience, variant => {
      const heroVariant = variant as PrimerComponentHero
      return {
        id: heroVariant?.sys?.id,
        heading: heroVariant?.fields?.heading,
        description: heroVariant?.fields?.description,
      }
    }),
  )

  // Define baseline experience (original content)
  const baseline: Baseline<{heading: string; description?: string}> = {
    id: component.sys.id,
    heading: component.fields.heading,
    description: component.fields.description,
  }

  return (
    // Wrap in fade-in animation container to smoothly reveal content after Ninetailed resolves
    <div className="anim-fade-in fast">
      {/* Render Experience component with baseline and variants */}
      <Experience
        {...baseline}
        experiences={experiences}
        component={({heading, description}: {heading: string; description?: string}) => (
          <ContentfulHeroLayout
            component={{
              ...component,
              fields: {
                ...component.fields,
                heading,
                description: description ?? component.fields.description,
              },
            }}
            paddingBlockEnd={paddingBlockEnd}
            analyticsContext={analyticsContext}
            {...props}
          />
        )}
      />
    </div>
  )
}
